import heapq

def top_k(a, k):
    """求前 k 大元素(降序返回)。维护一个大小为 k 的小顶堆:堆未满直接 push;
    堆满后若当前元素比堆顶(k 个里最小的)大,就用它替换堆顶。O(n log k)。"""
    if k <= 0:
        return []
    k = min(k, len(a))
    heap = []                               # 小顶堆,堆顶是当前前 k 大里最小的
    for x in a:
        if len(heap) < k:
            heapq.heappush(heap, x)
        elif x > heap[0]:
            heapq.heapreplace(heap, x)      # pop 最小再 push,一步到位
    return sorted(heap, reverse=True)
